    (175.0, 430.0, 1060.0, 46.0, 0.0),
    (238.0, -60.0, 420.0, 34.0, 7.0),
    (292.0, 520.0, 980.0, 26.0, 13.0),
    (338.0, 80.0, 560.0, 18.0, 21.0),
